#!/bin/bash
set -e
python3 - <<'PY'
import os,pathlib
p=pathlib.Path('/tmp/ai-youth-4938bb96d4b896e2.b64')
data=''
if p.exists():
    assert not p.is_symlink() and p.read_text()==data, 'Unexpected staging file'
else:
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    with os.fdopen(fd,'w') as f: f.write(data)
print('YOUTH_STAGE_OK')
PY
